/* @prim:begin 39-theme-toggle */
:root{color-scheme:dark;}
@media (prefers-color-scheme: light){:root:not([data-theme="dark"]){--bg:#f7f8fa;--surface:#ffffff;--surface-2:#eef1f5;--elevated:#eef1f5;--border:#d5dbe3;--text:#1c2430;--text-secondary:#475262;--muted:#566170;--dimmed:#475262;--cyan:#00606b;--cyan-bg:rgba(0,96,107,0.09);--green:#047857;--green-bg:rgba(4,120,87,0.09);--gold:#6b5400;--gold-bg:#fff3c4;--red:#b42344;--red-bg:rgba(180,35,68,0.08);color-scheme:light;}}
:root[data-theme="light"]{--bg:#f7f8fa;--surface:#ffffff;--surface-2:#eef1f5;--elevated:#eef1f5;--border:#d5dbe3;--text:#1c2430;--text-secondary:#475262;--muted:#566170;--dimmed:#475262;--cyan:#00606b;--cyan-bg:rgba(0,96,107,0.09);--green:#047857;--green-bg:rgba(4,120,87,0.09);--gold:#6b5400;--gold-bg:#fff3c4;--red:#b42344;--red-bg:rgba(180,35,68,0.08);color-scheme:light;}
.themebtn{display:inline-flex;align-items:center;min-height:44px;padding:0;margin:0 0 8px;font:inherit;font-size:var(--fs-body);color:var(--text-secondary);background:none;border:0;cursor:pointer;text-underline-offset:3px;}
.themebtn:hover,.themebtn:focus-visible{color:var(--cyan);text-decoration:underline;}
.themebtn:focus-visible{outline:2px solid var(--cyan);outline-offset:2px;}
@media print{:root{--bg:#f7f8fa;--surface:#ffffff;--surface-2:#eef1f5;--elevated:#eef1f5;--border:#d5dbe3;--text:#1c2430;--text-secondary:#475262;--muted:#566170;--dimmed:#475262;--cyan:#00606b;--cyan-bg:rgba(0,96,107,0.09);--green:#047857;--green-bg:rgba(4,120,87,0.09);--gold:#6b5400;--gold-bg:#fff3c4;--red:#b42344;--red-bg:rgba(180,35,68,0.08);color-scheme:light;} .themebtn{display:none!important;} body{background:#fff!important;}}
/* @prim:end 39-theme-toggle */
/* @prim:begin 49-pinned-card */
.pcard-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}
.pcard{border:1px solid var(--border);border-radius:var(--ds-r-md);background:var(--surface);overflow:hidden;container-type:inline-size}
.pcard[hidden]{display:none}
.pcard-h{position:relative;padding:14px 18px 16px;border-bottom:1px solid var(--border);background:var(--surface-2)}
.pcard-h h2{margin:0;padding-right:44px;font-size:1.15rem;line-height:1.3;font-weight:650;text-wrap:balance}
.pcard-h h2:focus{outline:none}
.pcard-h h2:focus-visible{outline:3px solid var(--cyan);outline-offset:4px;border-radius:var(--ds-r-xs)}
.pcard-meta{margin:8px 0 0;color:var(--text-secondary);font-size:.9rem;font-variant-numeric:tabular-nums}
.pcard-x{position:absolute;top:10px;right:12px;display:inline-grid;place-items:center;width:44px;height:44px;border:0;border-radius:var(--ds-r-sm);background:none;color:var(--text-secondary);cursor:pointer}
.pcard-x svg{width:1.125rem;height:1.125rem}
.pcard-x:hover{color:var(--text);background:var(--cyan-bg)}
.pcard-x:focus-visible{outline:3px solid var(--cyan);outline-offset:2px}
.pcard-b{padding:2px 18px 18px}
.pcard-s{padding:14px 0;border-top:1px solid var(--border)}
.pcard-s:first-child{border-top:0}
.pcard-s h3{margin:0 0 6px;font-size:.9rem;font-weight:600;line-height:1.4;color:var(--text-secondary)}
.pcard-s p{margin:0;line-height:1.55;text-wrap:pretty}
@container (min-width:520px){.pcard-s{display:grid;grid-template-columns:9.5rem minmax(0,1fr);gap:0 20px}.pcard-s h3{margin:2px 0 0}}
@media (min-width:961px){.pcard.is-pinned{position:fixed;z-index:30;right:16px;bottom:16px;width:min(25rem,calc(100vw - 32px));max-height:50vh;overflow:auto;overscroll-behavior:contain;border:0;border-radius:var(--ds-r-md);box-shadow:0 10px 12px -4px rgba(0,0,0,.26),0 2px 6px rgba(0,0,0,.10);transform:translateY(12px);opacity:0;visibility:hidden;transition:transform 160ms var(--ease-out),opacity 160ms var(--ease-out),visibility 0s linear 160ms}.pcard.is-pinned.on{transform:none;opacity:1;visibility:visible;transition:transform 260ms var(--ease-out),opacity 200ms var(--ease-out),visibility 0s}.pcard.is-static{border:0;box-shadow:0 10px 12px -4px rgba(0,0,0,.26),0 2px 6px rgba(0,0,0,.10);border-radius:var(--ds-r-md)}}
@media (max-width:960px){.pcard.is-pinned:not(.on){display:none}}
@media (prefers-reduced-motion:reduce){.pcard{transition:none!important}}
/* @prim:end 49-pinned-card */

