function kIcon(k){return '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+KI[k]+'</svg>';}
function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var PC=[{id:'k1',title:'Kickoff call',meta:['Task','Day 1','1 hour'],sections:[{h:'What you get',p:'A shared list of the tools and people in scope.'},{h:'Good to know',p:'Thirty minutes is enough; bring whoever runs the day to day.'}]},{id:'i1',title:'Front-line interviews',meta:['Task','Day 2','2 hours'],sections:[{h:'What you get',p:'Two short write-ups in plain language.'},{h:'Waits on you',p:'Two names and a time that suits them.'}]},{id:'r1',title:'Review call',meta:['Milestone','Day 5','1 hour'],sections:[{h:'What you get',p:'The scoped MVP plan, walked through together.'}]}];
function pcardHTML(n,uid){return '<header class="pcard-h"><h2 id="'+uid+'" tabindex="-1">'+kEsc(n.title)+'</h2><p class="pcard-meta">'+n.meta.map(kEsc).join(' · ')+'</p><button type="button" class="pcard-x" aria-label="Close details">'+kIcon('x')+'</button></header><div class="pcard-b">'+n.sections.map(function(s){return '<div class="pcard-s"><h3>'+kEsc(s.h)+'</h3><p>'+kEsc(s.p)+'</p></div>';}).join('')+'</div>';}
function kitPinnedCard(card,rows,uid){var from=null;function close(){card.classList.remove('on');card.hidden=true;if(from)from.focus();}
card.addEventListener('click',function(e){if(e.target.closest('.pcard-x'))close();});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!card.hidden)close();});
return function open(n,btn){from=btn;card.hidden=false;card.setAttribute('aria-labelledby',uid);card.innerHTML=pcardHTML(n,uid);card.scrollTop=0;requestAnimationFrame(function(){card.classList.add('on');card.querySelector('h2').focus({preventScroll:true});});};}
var stg=kSlot();stg.innerHTML='<div class="pcard-layout"><div role="list" aria-label="Items" style="display:grid;gap:6px"></div><section class="pcard is-pinned" aria-live="polite" hidden></section></div>';var lst=stg.querySelector('[role=list]'),cd=stg.querySelector('.pcard'),op=kitPinnedCard(cd,PC,'pc-stage-h');
PC.forEach(function(n){var w=document.createElement('div');w.setAttribute('role','listitem');var b=document.createElement('button');b.type='button';b.style.cssText='width:100%;min-height:44px;display:flex;align-items:center;padding:0 12px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text);font:inherit;text-align:left;cursor:pointer';b.textContent=n.title+' ('+n.meta[1]+')';b.onclick=function(){op(n,b);};w.appendChild(b);lst.appendChild(w);});
STATES.forEach(function(s,i){var c=document.createElement('section');c.className='pcard'+(s[0]==='wide'?' is-static':'');c.setAttribute('aria-labelledby','pc-s'+i);c.innerHTML=pcardHTML(PC[0],'pc-s'+i);kSlot(i).appendChild(c);});
